// Saca los que traen número de guía. Sin guía no hay nada que rastrear.
const oportunidades = $input.first().json.opportunities || [];
const salida = [];

for (const o of oportunidades) {
  const campos = o.customFields || [];
  const buscar = (clave) => {
    const c = campos.find(x => (x.fieldKey || '').endsWith(clave) || x.id === clave);
    return c ? (c.fieldValue ?? c.value) : null;
  };
  const guia = buscar('numero_guia');
  if (!guia) continue;
  salida.push({ json: { opportunityId: o.id, contactId: o.contactId, numero_guia: guia } });
}
return salida;

// Todas las guías en una sola llamada a Envia.
const guias = $input.all().map(i => i.json.numero_guia).filter(Boolean);
return guias.length ? [{ json: { trackingNumbers: guias } }] : [];

// Traduce el catálogo de estatus de Envia (28 valores en inglés, probado el 25 sep)
// a lo que nos importa: ¿llegó a sucursal? ¿ya lo entregaron? ¿se canceló o hay problema?
const r = $json;
if (r.meta === 'error') {
  // ponytail: si Envia falla, esta corrida no avisa nada; la siguiente hora lo reintenta.
  return [];
}
const entradas = $('Los que tienen guía').all().map(i => i.json);

// ponytail: sólo los estatus que vimos o que la referencia nombra; lo demás cae en en_transito.
const mapa = {
  created: 'creada',
  pickedup: 'en_transito', collected: 'en_transito', shipped: 'en_transito', intransit: 'en_transito',
  outfordelivery: 'en_reparto',
  readyforpickup: 'en_sucursal', availableforpickup: 'en_sucursal', atbranch: 'en_sucursal',
  delivered: 'entregado',
  canceled: 'cancelado', cancelled: 'cancelado',
  exception: 'incidencia', returned: 'incidencia', returntosender: 'incidencia'
};

return (r.data || []).map(t => {
  const crudo = String(t.status || '');
  const clave = crudo.toLowerCase().replace(/[^a-z]/g, '');
  const estado = mapa[clave] || 'en_transito';
  const entrada = entradas.find(x => x.numero_guia === t.trackingNumber) || {};
  return { json: { ...entrada, estado, estado_crudo: crudo,
                   entrega_estimada: t.estimatedDelivery || null, entregado_el: t.deliveredAt || null,
                   track_url: t.trackUrl || null,
                   avisar: !['creada', 'en_transito'].includes(estado),
                   mover_a: estado === 'entregado' ? $env.GHL_STAGE_ENTREGADO : null } };
});

// Saca la guía del contacto. Sin guía, se responde sin llamar a Envia.
const c = $json.contact || {};
const campos = c.customFields || [];
const buscar = (clave) => { const x = campos.find(f => (f.fieldKey || '').endsWith(clave) || f.id === clave); return x ? (x.fieldValue ?? x.value) : null; };
const guia = buscar('numero_guia');
return [{ json: { contactId: c.id, numero_guia: guia, track_url: buscar('track_url'), sin_guia: !guia } }];

// Mismo catálogo que «Traducir estatus», pero para una sola guía y en palabras para el bot.
const r = $json;
const previo = $('Guía del contacto').first().json;
if (r.meta === 'error' || !(r.data || []).length) {
  return [{ json: { ok: false, estatus: 'desconocido', estatus_texto: 'No pude consultar el rastreo ahora mismo; intenta en unos minutos.', track_url: previo.track_url } }];
}
const t = r.data[0];
const clave = String(t.status || '').toLowerCase().replace(/[^a-z]/g, '');
const camino = ['en_transito', 'Tu paquete ya va en camino.'];
const sucursal = ['en_sucursal', 'Tu paquete ya está en la sucursal, listo para recoger.'];
const incid = ['incidencia', 'Hubo un contratiempo con tu envío; ya lo estamos revisando.'];
const cancel = ['cancelado', 'Esa guía se canceló; te contactamos para resolverlo.'];
const mapa = { created: ['creada', 'Tu guía ya está generada y el paquete está por salir del almacén.'],
  pickedup: camino, collected: camino, shipped: camino, intransit: camino,
  outfordelivery: ['en_reparto', 'Tu paquete está en reparto, llega hoy.'],
  readyforpickup: sucursal, availableforpickup: sucursal, atbranch: sucursal,
  delivered: ['entregado', 'Tu paquete ya fue entregado.'],
  canceled: cancel, cancelled: cancel, exception: incid, returned: incid };
const [estado, texto] = mapa[clave] || camino;
const eta = t.estimatedDelivery ? ` Entrega estimada: ${String(t.estimatedDelivery).slice(0, 10)}.` : '';
return [{ json: { ok: true, estatus: estado, estatus_crudo: t.status, estatus_texto: texto + eta, entrega_estimada: t.estimatedDelivery, track_url: t.trackUrlSite || t.trackUrl || previo.track_url } }];
